create table if not exists official_source_registry(id uuid primary key default gen_random_uuid(),source_key text unique not null,source_type text not null,authority text not null default 'MEB',source_url text not null,parser_kind text not null default 'DOCUMENT',check_mode text not null default 'MANUAL_OR_WORKER',active boolean not null default true,last_checked_at timestamptz,last_changed_at timestamptz,last_content_hash text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists official_source_snapshots(id uuid primary key default gen_random_uuid(),source_id uuid not null references official_source_registry(id) on delete cascade,content_hash text not null,retrieved_at timestamptz not null default now(),http_status int,document_date date,effective_from date,effective_to date,decision_no text,title text,metadata jsonb not null default '{}'::jsonb,raw_location text,unique(source_id,content_hash));
create table if not exists official_source_change_queue(id uuid primary key default gen_random_uuid(),source_id uuid not null references official_source_registry(id) on delete cascade,snapshot_id uuid not null references official_source_snapshots(id) on delete cascade,previous_snapshot_id uuid references official_source_snapshots(id),change_type text not null default 'CONTENT_CHANGED',status text not null default 'DETECTED',parse_required boolean not null default true,approval_required boolean not null default true,effective_from date,parser_result jsonb not null default '{}'::jsonb,detected_at timestamptz not null default now(),parsed_at timestamptz,approved_at timestamptz,applied_at timestamptz,note text,unique(source_id,snapshot_id));
create index if not exists ix_source_change_queue_status on official_source_change_queue(status,detected_at);
create or replace function register_official_source_snapshot_v1(p_source_key text,p_source_type text,p_source_url text,p_content_hash text,p_authority text default 'MEB',p_http_status int default 200,p_document_date date default null,p_effective_from date default null,p_effective_to date default null,p_decision_no text default null,p_title text default null,p_metadata jsonb default '{}'::jsonb,p_raw_location text default null) returns table(source_id uuid,snapshot_id uuid,changed boolean,queue_id uuid) language plpgsql security definer set search_path=public as $$declare s uuid; prev uuid; snap uuid; q uuid; oldhash text; begin insert into official_source_registry(source_key,source_type,authority,source_url) values(p_source_key,p_source_type,coalesce(p_authority,'MEB'),p_source_url) on conflict(source_key) do update set source_type=excluded.source_type,authority=excluded.authority,source_url=excluded.source_url,updated_at=now() returning id,last_content_hash into s,oldhash; select id into prev from official_source_snapshots where source_id=s order by retrieved_at desc limit 1; insert into official_source_snapshots(source_id,content_hash,http_status,document_date,effective_from,effective_to,decision_no,title,metadata,raw_location) values(s,p_content_hash,p_http_status,p_document_date,p_effective_from,p_effective_to,p_decision_no,p_title,coalesce(p_metadata,'{}'::jsonb),p_raw_location) on conflict(source_id,content_hash) do update set retrieved_at=now(),http_status=excluded.http_status,metadata=official_source_snapshots.metadata||excluded.metadata returning id into snap; update official_source_registry set last_checked_at=now(),last_changed_at=case when last_content_hash is distinct from p_content_hash then now() else last_changed_at end,last_content_hash=p_content_hash,updated_at=now() where id=s; if oldhash is distinct from p_content_hash then insert into official_source_change_queue(source_id,snapshot_id,previous_snapshot_id,effective_from) values(s,snap,prev,p_effective_from) on conflict(source_id,snapshot_id) do update set effective_from=excluded.effective_from returning id into q; end if; return query select s,snap,(oldhash is distinct from p_content_hash),q; end$$;
create or replace function mark_official_source_change_parsed_v1(p_queue_id uuid,p_parser_result jsonb,p_effective_from date default null,p_approval_required boolean default true) returns void language sql security definer set search_path=public as $$update official_source_change_queue set parser_result=coalesce(p_parser_result,'{}'::jsonb),effective_from=coalesce(p_effective_from,effective_from),approval_required=p_approval_required,status=case when p_approval_required then 'PARSED_AWAITING_APPROVAL' else 'PARSED_READY' end,parsed_at=now() where id=p_queue_id$$;
create or replace function approve_official_source_change_v1(p_queue_id uuid,p_calendar_title text default null,p_calendar_event_type text default 'OFFICIAL_CHANGE') returns uuid language plpgsql security definer set search_path=public as $$declare d date; eid uuid; t text; begin update official_source_change_queue set status='APPROVED',approved_at=now() where id=p_queue_id returning effective_from into d; if d is not null and p_calendar_title is not null then select title into t from official_source_snapshots s join official_source_change_queue q on q.snapshot_id=s.id where q.id=p_queue_id; insert into school_calendar_events(event_type,title,starts_on,ends_on,blocks_teaching,counts_as_workday,all_day,note,source_note,conditional,parsed_from_source) values(p_calendar_event_type,p_calendar_title,d,d,false,true,true,'Resmî kaynak değişikliğinin yürürlük tarihi',coalesce(t,'Resmî kaynak')||' / queue:'||p_queue_id::text,false,true) returning id into eid; end if; return eid; end$$;